#!/usr/bin/env python3
"""One-off real AWS Lambda/Step Functions evidence; owned resources only."""
import argparse
import base64
import datetime
import hashlib
import io
import json
import os
from pathlib import Path
import time
import traceback
import uuid
import zipfile

from aws_cli import observe, result, run

ROOT = Path(__file__).resolve().parents[2]
DEST = ROOT / 'testdata/aws/stepfunctions/lambda_integrations.json'
REGION = 'us-west-2'
ACCOUNT = '000000000000'
ENV = dict(os.environ, AWS_REGION=REGION, AWS_DEFAULT_REGION=REGION, AWS_MAX_ATTEMPTS='1')
HANDLER = '''import json

class ExplicitProbeError(Exception):
    pass

def invoke(event, context):
    print("PROBE_EVENT " + json.dumps(event, ensure_ascii=False, sort_keys=True))
    if isinstance(event, dict) and event.get("raise_error"):
        raise ExplicitProbeError("explicit native probe failure")
    return {"received": event, "python_type": type(event).__name__, "unicode": "snowman \\u2603"}
'''
C = {}


def now():
    return datetime.datetime.now(datetime.timezone.utc).isoformat()


def save():
    DEST.write_text(json.dumps(C, ensure_ascii=False, indent=2) + '\n')


def record(label, service, operation, parameters, cleanup=False):
    row = {'label': label, 'service': service, 'operation': operation,
           'region': 'aws-global' if service in ('iam', 'sts') else REGION,
           'input': parameters, 'started_at': now()}
    C['observations'].append(row)
    save()
    row['result'] = observe(service, operation, parameters, ENV)
    row['finished_at'] = now()
    if cleanup:
        row['cleanup'] = True
    save()
    print(label + ': ' + row['result']['code'], flush=True)
    return row['result']


def require(label, service, operation, parameters, cleanup=False):
    response = record(label, service, operation, parameters, cleanup)
    if response['code'] != 'Success':
        raise RuntimeError(label + ': ' + json.dumps(response))
    return response['output']


def identity():
    actual = require('identity', 'sts', 'get-caller-identity', {})
    if actual['Account'] != ACCOUNT:
        raise RuntimeError('Refusing account mismatch')


def initialize():
    prefix = 'stackd-sfn-lambda-' + uuid.uuid4().hex[:10]
    C.update(service='stepfunctions', account=ACCOUNT, region=REGION, prefix=prefix,
             captured_at=now(), transport='AWS CLI through scripts/aws/aws_cli.py. Invoke response body saved as bytes separately from native CLI metadata. StepFunctions histories preserved unchanged; top-level CLI modeled timestamps are not claimed as wire timestamp encoding.',
             redaction='No credentials exported or recorded; no task tokens generated. Native account/ARN/request IDs and body bytes retained. Lambda TraceId and timestamps are dynamic observations, not exact assertions.',
             bounds={'state_machines': 1, 'roles': 2, 'lambda_functions': 1, 'memory_mb': 128, 'lambda_timeout_seconds': 3, 'max_executions': 24},
             resources={'function_name': prefix, 'function_arn': f'arn:aws:lambda:{REGION}:{ACCOUNT}:function:{prefix}',
                        'lambda_role_name': prefix + '-lambda', 'states_role_name': prefix + '-states',
                        'log_group': '/aws/lambda/' + prefix,
                        'machine_name': prefix, 'machine_arn': f'arn:aws:states:{REGION}:{ACCOUNT}:stateMachine:{prefix}'},
             observations=[], executions={}, cleanup={}, source_revisions=[], probe_errors=[])


def setup():
    r = C['resources']
    require('create-log-group', 'logs', 'create-log-group', {'logGroupName': r['log_group']})
    r['log_group_created'] = True
    trust_lambda = {'Version': '2012-10-17', 'Statement': [{'Effect': 'Allow', 'Principal': {'Service': 'lambda.amazonaws.com'}, 'Action': 'sts:AssumeRole'}]}
    trust_states = {'Version': '2012-10-17', 'Statement': [{'Effect': 'Allow', 'Principal': {'Service': 'states.amazonaws.com'}, 'Action': 'sts:AssumeRole', 'Condition': {'StringEquals': {'aws:SourceAccount': ACCOUNT}, 'ArnEquals': {'aws:SourceArn': r['machine_arn']}}}]}
    log_arn = f'arn:aws:logs:{REGION}:{ACCOUNT}:log-group:' + r['log_group'] + ':*'
    policies = {'lambda': {'Version': '2012-10-17', 'Statement': [{'Effect': 'Allow', 'Action': ['logs:CreateLogStream', 'logs:PutLogEvents'], 'Resource': log_arn}]},
                'states': {'Version': '2012-10-17', 'Statement': [{'Effect': 'Allow', 'Action': 'lambda:InvokeFunction', 'Resource': r['function_arn']}]}}
    C['policies'] = policies
    for kind, trust in [('lambda', trust_lambda), ('states', trust_states)]:
        role = require('create-role-' + kind, 'iam', 'create-role', {'RoleName': r[kind + '_role_name'], 'AssumeRolePolicyDocument': json.dumps(trust)})['Role']
        r[kind + '_role_arn'] = role['Arn']
        r[kind + '_role_created'] = True
        save()
        require('put-policy-' + kind, 'iam', 'put-role-policy', {'RoleName': role['RoleName'], 'PolicyName': 'owned-only', 'PolicyDocument': json.dumps(policies[kind])})
    archive = io.BytesIO()
    with zipfile.ZipFile(archive, 'w', compression=zipfile.ZIP_STORED) as package:
        package.writestr(zipfile.ZipInfo('entry.py', (2026, 1, 1, 0, 0, 0)), HANDLER.encode('utf-8'))
    zip_bytes = archive.getvalue()
    zip_path = Path('/tmp/' + C['prefix'] + '.zip')
    zip_path.write_bytes(zip_bytes)
    C['artifact'] = {'handler_source_utf8': HANDLER, 'zip_base64': base64.b64encode(zip_bytes).decode(), 'zip_sha256': hashlib.sha256(zip_bytes).hexdigest(), 'temporary_zip_path': str(zip_path)}
    params = {'FunctionName': r['function_name'], 'Runtime': 'python3.12', 'Role': r['lambda_role_arn'], 'Handler': 'entry.invoke', 'Code': {'ZipFile': C['artifact']['zip_base64']}, 'Timeout': 3, 'MemorySize': 128, 'TracingConfig': {'Mode': 'PassThrough'}}
    for attempt in range(16):
        response = record('create-function-' + str(attempt), 'lambda', 'create-function', params)
        if response['code'] == 'Success':
            r['function_created'] = True
            save()
            break
        if response['code'] != 'InvalidParameterValueException' or 'cannot be assumed' not in json.dumps(response):
            raise RuntimeError(json.dumps(response))
        time.sleep(4)
    else:
        raise RuntimeError('Owned Lambda trust propagation exceeded bounded wait')
    for attempt in range(30):
        config = require('function-ready-' + str(attempt), 'lambda', 'get-function-configuration', {'FunctionName': r['function_name']})
        if config['State'] == 'Active':
            break
        if config['State'] == 'Failed':
            raise RuntimeError('Lambda deployment failed')
        time.sleep(2)
    else:
        raise RuntimeError('Lambda readiness exceeded bounded wait')
    sdk = {'Type': 'Task', 'Resource': 'arn:aws:states:::aws-sdk:lambda:invoke', 'Parameters': {'FunctionName': r['function_arn'], 'Payload.$': '$.payload'}, 'End': True}
    optimized = {'Type': 'Task', 'Resource': 'arn:aws:states:::lambda:invoke', 'Parameters': {'FunctionName': r['function_arn'], 'Payload.$': '$.payload'}, 'End': True}
    sdk_omitted = {'Type': 'Task', 'Resource': 'arn:aws:states:::aws-sdk:lambda:invoke', 'Parameters': {'FunctionName': r['function_arn']}, 'End': True}
    sdk_event = json.loads(json.dumps(sdk)); sdk_event['Parameters']['InvocationType'] = 'Event'
    optimized_event = json.loads(json.dumps(optimized)); optimized_event['Parameters']['InvocationType'] = 'Event'
    definition = {'StartAt': 'Route', 'TimeoutSeconds': 20, 'States': {'Route': {'Type': 'Choice', 'Choices': [{'Variable': '$.route', 'StringEquals': name, 'Next': name} for name in ['Sdk', 'SdkOmitted', 'SdkEvent', 'Optimized', 'OptimizedEvent', 'Direct']], 'Default': 'BadRoute'}, 'Sdk': sdk, 'SdkOmitted': sdk_omitted, 'SdkEvent': sdk_event, 'Optimized': optimized, 'OptimizedEvent': optimized_event, 'Direct': {'Type': 'Task', 'Resource': r['function_arn'], 'InputPath': '$.payload', 'End': True}, 'BadRoute': {'Type': 'Fail', 'Error': 'BadRoute'}}}
    C['definition'] = definition
    require('create-machine', 'stepfunctions', 'create-state-machine', {'name': r['machine_name'], 'roleArn': r['states_role_arn'], 'definition': json.dumps(definition), 'type': 'STANDARD'})
    r['machine_created'] = True
    save()


def direct_invoke(label, payload_text):
    r = C['resources']
    body_path = Path('/tmp/' + C['prefix'] + '-' + label + '.body')
    options = ['--function-name', r['function_name'], '--payload', payload_text, '--cli-binary-format', 'raw-in-base64-out', '--log-type', 'Tail', '--cli-error-format', 'json', '--cli-connect-timeout', '10', '--cli-read-timeout', '20', str(body_path)]
    started = now()
    process = run('lambda', 'invoke', env=ENV, options=options, timeout=40)
    observed = result(process, cli_message=None)
    if process.returncode and process.stderr.strip().startswith('{'):
        observed = {'code': json.loads(process.stderr).get('Code', 'CLIError'), 'error': json.loads(process.stderr)}
    row = {'label': label, 'service': 'lambda', 'operation': 'invoke', 'region': REGION, 'input': {'FunctionName': r['function_name'], 'PayloadUtf8': payload_text, 'LogType': 'Tail'}, 'started_at': started, 'finished_at': now(), 'result': observed}
    if body_path.exists():
        body = body_path.read_bytes()
        row['response_body'] = {'base64': base64.b64encode(body).decode(), 'hex': body.hex(), 'utf8': body.decode('utf-8'), 'length_bytes': len(body)}
        if body:
            row['response_body']['parsed_json'] = json.loads(body)
        body_path.unlink()
    if observed.get('output', {}).get('LogResult'):
        row['decoded_log_utf8'] = base64.b64decode(observed['output']['LogResult']).decode('utf-8')
    C['observations'].append(row)
    save()
    print(label + ': ' + json.dumps(row.get('response_body', {}).get('parsed_json', observed)), flush=True)


def execute(label, route, payload=None):
    if label in C['executions']:
        raise RuntimeError('Refusing repeated execution label ' + label)
    if len(C['executions']) >= 24:
        raise RuntimeError('Execution cap reached')
    input_value = {'route': route, 'payload': payload}
    response = require('start-' + label, 'stepfunctions', 'start-execution', {'stateMachineArn': C['resources']['machine_arn'], 'name': label, 'input': json.dumps(input_value, ensure_ascii=False)})
    entry = {'arn': response['executionArn'], 'input': input_value}
    C['executions'][label] = entry
    save()
    for attempt in range(20):
        description = require('describe-' + label + '-' + str(attempt), 'stepfunctions', 'describe-execution', {'executionArn': entry['arn']})
        if description['status'] != 'RUNNING':
            entry['description'] = description
            break
        time.sleep(2)
    else:
        require('stop-' + label, 'stepfunctions', 'stop-execution', {'executionArn': entry['arn'], 'error': 'ProbeBoundReached'})
        description = require('stopped-' + label, 'stepfunctions', 'describe-execution', {'executionArn': entry['arn']})
        if description['status'] == 'RUNNING':
            raise RuntimeError('Execution failed bounded stop')
        entry['description'] = description
    entry['history'] = require('history-' + label, 'stepfunctions', 'get-execution-history', {'executionArn': entry['arn'], 'includeExecutionData': True})
    entry['projection'] = {'status': description['status']}
    for key in ('output', 'error', 'cause'):
        if key in description:
            entry['projection'][key] = json.loads(description[key]) if key == 'output' else description[key]
    save()
    print('CASE ' + label + ': ' + json.dumps(entry['projection'], ensure_ascii=False), flush=True)


def sdk_cases():
    direct_invoke('direct-api-object', json.dumps({'marker': 'direct-api-object', 'value': [1, True, None, 'snowman \u2603']}, ensure_ascii=False))
    execute('sdk-payload-object', 'Sdk', {'marker': 'sdk-object', 'value': [1, True, None, 'snowman \u2603']})
    execute('sdk-payload-json-string', 'Sdk', json.dumps({'marker': 'sdk-json-string', 'value': 7}))
    execute('sdk-payload-base64-string', 'Sdk', base64.b64encode(json.dumps({'marker': 'sdk-base64', 'value': 8}).encode()).decode())
    execute('sdk-payload-null', 'Sdk', None)
    execute('sdk-payload-omitted', 'SdkOmitted')


def remaining_cases():
    direct_invoke('direct-api-json-string', json.dumps('plain native string'))
    direct_invoke('direct-api-null', 'null')
    direct_invoke('direct-api-function-error', json.dumps({'raise_error': True}))
    execute('sdk-function-error-object', 'Sdk', {'raise_error': True})
    execute('sdk-function-error-json-string', 'Sdk', json.dumps({'raise_error': True}))
    execute('optimized-success', 'Optimized', {'marker': 'optimized-object', 'value': [1, True, None, 'snowman \u2603']})
    execute('optimized-json-string', 'Optimized', json.dumps({'marker': 'optimized-json-string'}))
    execute('optimized-null', 'Optimized', None)
    execute('optimized-function-error', 'Optimized', {'raise_error': True})
    execute('direct-arn-success', 'Direct', {'marker': 'direct-arn-object', 'value': [1, True, None, 'snowman \u2603']})
    execute('direct-arn-function-error', 'Direct', {'raise_error': True})
    execute('sdk-event', 'SdkEvent', {'marker': 'sdk-event-delivery'})
    execute('optimized-event', 'OptimizedEvent', {'marker': 'optimized-event-delivery'})
    for attempt in range(16):
        logs = require('event-delivery-logs-' + str(attempt), 'logs', 'filter-log-events', {'logGroupName': C['resources']['log_group']})
        text = '\n'.join(event['message'] for event in logs.get('events', []))
        if 'sdk-event-delivery' in text and 'optimized-event-delivery' in text:
            C['async_deliveries_observed'] = True
            break
        time.sleep(3)
    else:
        C['async_deliveries_observed'] = False
    save()


def cleanup():
    r = C['resources']
    errors = []
    def clean(label, service, operation, parameters, accepted=('Success',)):
        response = record(label, service, operation, parameters, True)
        if response['code'] not in accepted:
            errors.append({'label': label, 'response': response})
        return response
    if r.get('machine_created'):
        running = clean('cleanup-list-running', 'stepfunctions', 'list-executions', {'stateMachineArn': r['machine_arn'], 'statusFilter': 'RUNNING'})
        for entry in running.get('output', {}).get('executions', []):
            clean('cleanup-stop-execution', 'stepfunctions', 'stop-execution', {'executionArn': entry['executionArn'], 'error': 'ProbeCleanup'})
        all_terminal = True
        for label, entry in C['executions'].items():
            output = clean('cleanup-terminal-' + label, 'stepfunctions', 'describe-execution', {'executionArn': entry['arn']}).get('output', {})
            all_terminal = all_terminal and output.get('status') in ('SUCCEEDED', 'FAILED', 'TIMED_OUT', 'ABORTED')
        C['cleanup']['all_executions_terminal'] = all_terminal
        if not all_terminal:
            raise RuntimeError('Refusing teardown before terminal executions')
        clean('cleanup-delete-machine', 'stepfunctions', 'delete-state-machine', {'stateMachineArn': r['machine_arn']})
    if r.get('function_created'):
        clean('cleanup-delete-function', 'lambda', 'delete-function', {'FunctionName': r['function_name']}, ('Success', 'ResourceNotFoundException'))
        absent = clean('cleanup-function-absent', 'lambda', 'get-function-configuration', {'FunctionName': r['function_name']}, ('ResourceNotFoundException',))
        C['cleanup']['function_absent'] = absent['code'] == 'ResourceNotFoundException'
    if r.get('log_group_created'):
        clean('cleanup-delete-log-group', 'logs', 'delete-log-group', {'logGroupName': r['log_group']}, ('Success', 'ResourceNotFoundException'))
        logs = clean('cleanup-log-group-absent', 'logs', 'describe-log-groups', {'logGroupNamePrefix': r['log_group']})
        C['cleanup']['log_group_absent'] = logs['code'] == 'Success' and not logs['output']['logGroups']
    for kind in ('states', 'lambda'):
        if r.get(kind + '_role_created'):
            clean('cleanup-delete-policy-' + kind, 'iam', 'delete-role-policy', {'RoleName': r[kind + '_role_name'], 'PolicyName': 'owned-only'}, ('Success', 'NoSuchEntity'))
            clean('cleanup-delete-role-' + kind, 'iam', 'delete-role', {'RoleName': r[kind + '_role_name']}, ('Success', 'NoSuchEntity'))
            response = clean('cleanup-role-absent-' + kind, 'iam', 'get-role', {'RoleName': r[kind + '_role_name']}, ('NoSuchEntity',))
            C['cleanup'][kind + '_role_absent'] = response['code'] == 'NoSuchEntity'
    if r.get('machine_created'):
        for attempt in range(90):
            response = clean('cleanup-machine-absent-' + str(attempt), 'stepfunctions', 'describe-state-machine', {'stateMachineArn': r['machine_arn']}, ('Success', 'StateMachineDoesNotExist'))
            if response['code'] == 'StateMachineDoesNotExist':
                C['cleanup']['machine_absent'] = True
                break
            time.sleep(4)
        else:
            C['cleanup']['machine_absent'] = False
    if C.get('artifact'):
        path = Path(C['artifact']['temporary_zip_path'])
        path.unlink(missing_ok=True)
        C['cleanup']['temporary_zip_absent'] = not path.exists()
    C['cleanup_errors'] = errors
    C['cleanup_complete'] = not errors and all(C['cleanup'].values())
    C['finished_at'] = now()
    save()
    if not C['cleanup_complete']:
        raise RuntimeError('Cleanup remains incomplete: ' + json.dumps(C['cleanup']))


def main():
    args = argparse.ArgumentParser()
    args.add_argument('phase', choices=['setup', 'sdk', 'remaining', 'cleanup'])
    phase = args.parse_args().phase
    if DEST.exists():
        C.update(json.loads(DEST.read_text()))
        if phase == 'setup':
            raise RuntimeError('Refusing setup replay')
    else:
        if phase != 'setup':
            raise RuntimeError('Missing setup fixture')
        initialize()
    source = Path(__file__).read_text()
    revision = {'path': str(Path(__file__).relative_to(ROOT)), 'sha256': hashlib.sha256(source.encode()).hexdigest(), 'text': source}
    if not C['source_revisions'] or C['source_revisions'][-1]['sha256'] != revision['sha256']:
        C['source_revisions'].append(revision)
    C['probe_script'] = revision
    try:
        identity()
        {'setup': setup, 'sdk': sdk_cases, 'remaining': remaining_cases, 'cleanup': cleanup}[phase]()
    except Exception:
        C['probe_errors'].append({'phase': phase, 'at': now(), 'traceback': traceback.format_exc()})
        save()
        raise
    save()


if __name__ == '__main__':
    main()

